for name, (title, page, sels, effects, what, knobs) in C.items():
    d = os.path.join('lib/components', name)
    os.makedirs(d, exist_ok=True)
    markup = '\n\n'.join(pick(s) for s in sels if pick(s))
    open(d + '/markup.html', 'w', encoding='utf8').write('<!-- ' + title + ' — copy into a page; fill hooks (data-fill="...") are rendered by js/main.js -->\n' + markup + '\n')
    scripts = ('<script src="../../../js/data.js"></script>\n<script src="../../generators/art.js"></script><script src="../../generators/clouds.js"></script>\n'
               '<script src="https://cdn.jsdelivr.net/npm/gsap@3.15/dist/gsap.min.js"></script><script src="https://cdn.jsdelivr.net/npm/gsap@3.15/dist/ScrollTrigger.min.js"></script><script src="https://unpkg.com/lenis@1.3.21/dist/lenis.min.js"></script>\n'
               '<script src="../../core/core.js"></script>\n' + ''.join('<script src="../../fx/%s.js"></script>' % n for n in FX) + '\n<script src="../../../js/main.js"></script>')
    body_tail = '<div style="height:60vh;display:grid;place-items:center;background:var(--ivory);color:var(--muted);font:700 .8rem var(--sans);letter-spacing:.2em;text-transform:uppercase">End of demo</div>'
    demo = ('<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>' + title + '</title>'
            '<script>document.documentElement.classList.add("js");try{sessionStorage.removeItem("chuksSeen");sessionStorage.removeItem("chuksWipe")}catch(e){}</script>'
            '<link href="https://fonts.googleapis.com/css2?family=Fraunces:ital,opsz,wght,SOFT@0,9..144,300..600,0..100;1,9..144,300..600,0..100&family=Manrope:wght@400;500;600;700;800&display=swap" rel="stylesheet">'
            '<link rel="stylesheet" href="../../lib.css"></head><body data-page="' + page + '"' + (' class="is-loading"' if name == 'preloader-tube-iris' else '') + '>'
            '<main id="main">' + markup + '</main>' + body_tail + '<div id="ftr"></div>' + scripts + '</body></html>')
    open(d + '/demo.html', 'w', encoding='utf8').write(demo)
    css_note = 'style.css' if os.path.exists(d + '/style.css') else '(styles live in core/tokens-base.css)'
    readme = ('# ' + title + '\n\n' + what + '\n\n## Files\n- `markup.html` — the HTML (copy into a page)\n- `' + css_note + '` — the component styles (imported by `lib/lib.css`)\n'
              '- effect code: `' + ', '.join('Lab.run(\'' + e + '\')' for e in effects) + '`' + (' in `lib/fx/`' if effects else ' (none, CSS only)') + '\n- `demo.html` — standalone preview (serve the ChuksLab folder, open this file)\n\n'
              '## Tuning knobs\n' + ''.join('- ' + k + '\n' for k in knobs) + '\n## Needs\nGSAP 3.15 + ScrollTrigger, Lenis, `lib/core/core.js`' + (', `lib/generators/clouds.js`' if 'clouds' in effects else '') + (', `lib/generators/art.js`' if name == 'hscroll-cards' or name == 'inner-page-kit' else '') + '.\n')
    open(d + '/README.md', 'w', encoding='utf8').write(readme)
    print(name, len(markup))
